question.solution:
class DNode:
    def __init__(self, val=0, prev=None, next=None):
        self.val = val
        self.prev = prev
        self.next = next

def dremove_all(head, x):
    node = head
    while node is not None:
        nxt = node.next
        if node.val == x:
            if node.prev is not None:
                node.prev.next = node.next
            else:
                head = node.next
            if node.next is not None:
                node.next.prev = node.prev
        node = nxt
    return head

def dbuild(values):
    head = None
    tail = None
    for v in values:
        node = DNode(v)
        node.prev = tail
        if tail is None:
            head = node
        else:
            tail.next = node
        tail = node
    return head

def forward(head):
    out = []
    while head is not None:
        out.append(head.val)
        head = head.next
    return out

def backward_values(head):
    node = head
    if node is None:
        return []
    while node.next is not None:
        node = node.next
    out = []
    while node is not None:
        out.append(node.val)
        node = node.prev
    return out

print(forward(dremove_all(dbuild([1, 2, 3]), 1)))
print(backward_values(dremove_all(dbuild([1, 2, 3]), 1)))
print(dremove_all(dbuild([]), 1))
print(dremove_all(dbuild([9, 9]), 9))

