def _dcheck(head, expected):
    forward = []
    node = head
    prev = None
    while node is not None:
        if node.prev is not prev:
            return False, '结点的 prev 指针没接对（在第 %d 个结点处断了）' % (len(forward) + 1,)
        forward.append(node.val)
        prev = node
        node = node.next
    if forward != expected:
        return False, '正向应为 %r，实际 %r' % (expected, forward)
    back = []
    while prev is not None:
        back.append(prev.val)
        prev = prev.prev
    if back != expected[::-1]:
        return False, '从尾部往前的方向接错了：%r' % (back,)
    return True, ''
